import sys,json
t=sys.stdin.read(); body,code=t.rsplit('\n',2)[0],t.rsplit('\n',2)[1]; print(code)
d=json.loads(body)
for k,v in d.items():
  if not isinstance(v,list): print(k,v)
for c in d.get('children',d.get('items',[])): print(c.get('sunid'),c.get('sccs'),c.get('description'))
"; curl -s -w '\n%{http_code}\n' "$B/releases/2.08/sunids/54235/parents" | head -c 1500

